// index.js
import React, { useState } from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { ComboBox } from 'carbon-components-react';

const items = [
  { id: 'option-1', label: 'Option 1' },
  { id: 'option-2', label: 'Option 2' },
  { id: 'option-3', label: 'Option 3' },
];

function Demo() {
  const [selectedItem, setSelectedItem] = useState(items[0]);
  const [selectedItem2, setSelectedItem2] = useState(items[0]);

  return (
    <div style={{ padding: '2rem', display: 'grid', rowGap: '2rem', maxWidth: 400 }}>
      {/* 1. Invalid combo box: shows invalid red border, warning icon, and clear pill */}
      <ComboBox
        id="combobox-invalid"
        items={items}
        itemToString={item => item.label}
        placeholder="This is not a value."
        initialSelectedItem={selectedItem}
        onChange={({ selectedItem }) => setSelectedItem(selectedItem)}
        invalid={true}
        invalidText="Validation message here"
      />

      {/* 2. Valid combo box: shows selected item with clear pill (X) */}
      <ComboBox
        id="combobox-valid"
        items={items}
        itemToString={item => item.label}
        placeholder="Combobox title"
        initialSelectedItem={selectedItem2}
        onChange={({ selectedItem }) => setSelectedItem2(selectedItem)}
      />
    </div>
  );
}

ReactDOM.render(<Demo />, document.getElementById('root'));
